insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('e4f57407-1924-4c76-baef-7e28f7511c72', '1dcee0c7-abf1-4fd0-b340-0c043e30e2c0', $$inleiding — biobrandstoffen en broeikaseffect$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-hexaan-uit-cellulose-context1.png$$,
   $$Wereldwijd is er een toenemende aandacht voor het maken van biobrandstoffen uit biomassa. Gelet op duurzaamheid verdient het verbranden van biobrandstoffen de voorkeur boven het verbranden van fossiele brandstoffen. Zo draagt bijvoorbeeld het verbranden van fossiele brandstoffen meer bij aan het versterkt broeikaseffect dan het verbranden van biobrandstoffen.$$, 'inline'),
  ('9d59d775-f536-45c1-9e74-3a4264369a56', '1dcee0c7-abf1-4fd0-b340-0c043e30e2c0', $$experiment cellulose tot hexaan — opzet$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-hexaan-uit-cellulose-context2.png$$,
   $$Biomassa bestaat voor een groot deel uit cellulose. Onderzoekers hebben ontdekt dat cellulose kan worden omgezet tot hexaan. Dit experiment is vereenvoudigd weergegeven in figuur 1. Een kleine reactor werd gevuld met water, dodecaan (C₁₂H₂₆), cellulose, twee verschillende katalysatoren en waterstof (figuur 1a). Het reactiemengsel werd vervolgens gedurende een aantal uren verwarmd, terwijl het krachtig werd geroerd (figuur 1b). Na het experiment werd het reactiemengsel geanalyseerd.$$, 'inline'),
  ('2176201f-6a23-4857-b936-9b6ee5681bb1', '1dcee0c7-abf1-4fd0-b340-0c043e30e2c0', $$figuur 1 — experimentopstelling (start, tijdens, na experiment)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-hexaan-uit-cellulose-context3.png$$,
   $$figuur 1: drie schematische weergaven van de reactor. 1a (start experiment): van boven naar onder een laag waterstof, een laag dodecaan, en water en cellulose met een roerder, met katalysatoren onderin. 1b (tijdens het experiment): het reactiemengsel wordt krachtig geroerd (open en gevulde bolletjes door elkaar). 1c (na het experiment): een laag waterstof, een laag dodecaan en hexaan, en water met overgebleven cellulose, met de katalysatoren onderin.$$, 'inline'),
  ('4a9261ec-8e06-45ee-8abe-cdd9b014f48f', '1dcee0c7-abf1-4fd0-b340-0c043e30e2c0', $$hydrolyse cellulose tot glucose, omzetting tot hexaan$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-hexaan-uit-cellulose-context4.png$$,
   $$Tijdens het experiment wordt eerst cellulose gehydrolyseerd tot glucose. Vervolgens wordt glucose door een reactie met waterstof omgezet tot hexaan (C₆H₁₄) en water. Na de reactie mengt het gevormde hexaan zich met de laag dodecaan (zie figuur 1c).$$, 'inline'),
  ('c40a7189-8809-4f03-a853-3bb2e7d61583', '1dcee0c7-abf1-4fd0-b340-0c043e30e2c0', $$cellulose is polysacharide van glucose-eenheden — uitwerkbijlage vraag 2$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-hexaan-uit-cellulose-context5.png$$,
   $$Cellulose is een polysacharide die uitsluitend is opgebouwd uit glucose-eenheden. Op de uitwerkbijlage is de vergelijking van de hydrolyse van het uiteinde van een cellulosemolecuul onvolledig weergegeven.$$, 'inline'),
  ('de306272-8d57-4363-aa95-0c706cf5fb60', '1dcee0c7-abf1-4fd0-b340-0c043e30e2c0', $$uitwerkbijlage vraag 2 — hydrolyse cellulose-uiteinde$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-hexaan-uit-cellulose-context6.png$$,
   $$Uitwerkbijlage bij vraag 2: onvolledige reactievergelijking van de hydrolyse van het uiteinde van een cellulosemolecuul, met de structuurformule van een keten van drie aan elkaar gekoppelde glucose-eenheden (elk met CH₂OH, OH-groepen en een golflijn die de rest van de keten aangeeft) links van een pijl, gevolgd door "+ .............. →". Daaronder twee open regels en onderaan de invulregel "…………………… + ……………………" voor de twee afgesplitste glucosemoleculen. Vraagnummer 2 staat linksboven.$$, 'uitwerkbijlage'),
  ('68a4331a-e994-4263-a760-c6506f98faa7', '1dcee0c7-abf1-4fd0-b340-0c043e30e2c0', $$water en dodecaan mengen niet goed$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-hexaan-uit-cellulose-context7.png$$,
   $$De vloeistoffen water en dodecaan (C₁₂H₂₆) mengen niet goed (zie figuur 1a en 1c).$$, 'inline'),
  ('2aa75431-a5cd-4ff2-b15c-ed4ecc019f5e', '1dcee0c7-abf1-4fd0-b340-0c043e30e2c0', $$experimentgegevens — 0,50 g cellulose, 12,0 uur, 2,56·10⁻³ mol hexaan$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-hexaan-uit-cellulose-context8.png$$,
   $$Bij een experiment werd 0,50 g cellulose in een mengsel van water, dodecaan, waterstof en de twee katalysatoren gebracht. Het ontstane mengsel werd gedurende 12,0 uur geroerd bij een temperatuur van 190 °C. Na 12,0 uur was 2,56·10⁻³ mol hexaan gevormd.$$, 'inline'),
  ('36fac315-1d5a-4d4c-a636-604f6cac72f0', '1dcee0c7-abf1-4fd0-b340-0c043e30e2c0', $$hogere temperatuur — isomeren van hexaan$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-hexaan-uit-cellulose-context9.png$$,
   $$Als de temperatuur bij dit experiment hoger zou zijn dan 190 °C, zouden behalve hexaan ook isomeren van hexaan ontstaan.$$, 'inline'),

  ('e2688ec9-558e-4906-8aa4-44a172738781', '56b72be2-7602-4b82-a6f1-d9fc2438e8a2', $$inleiding — power-to-ammonia energieopslag$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-power-to-ammonia-context1.png$$,
   $$Wind-energie en zonne-energie kunnen nog niet grootschalig worden opgeslagen in Nederland. Daardoor kunnen deze duurzame energievormen, wanneer er veel wind of zon is, niet altijd optimaal benut worden. Op de Technische Universiteit Delft is onderzoek gedaan naar de mogelijkheid om de energie-overschotten op te slaan in de vorm van ammoniak (NH₃). Deze manier van energieopslag wordt het 'power-to-ammonia'-proces genoemd en bestaat uit vier stappen:$$, 'inline'),
  ('eefa8d53-5d5f-45a0-8e29-1b43656ed01a', '56b72be2-7602-4b82-a6f1-d9fc2438e8a2', $$stappen 1 t/m 4 — waterstoffabriek, luchtscheider, ammoniakfabriek, opslag$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-power-to-ammonia-context2.png$$,
   $$Stap 1: in een waterstoffabriek worden wind-energie en zonne-energie gebruikt om water door middel van elektrolyse om te zetten tot waterstof en zuurstof. Stap 2: in een luchtscheider wordt stikstof gescheiden van de overige gassen die in lucht voorkomen. Stap 3: in een ammoniakfabriek reageert waterstof vervolgens met stikstof tot ammoniakgas. Stap 4: ammoniakgas wordt vloeibaar gemaakt en daarna opgeslagen in tanks.$$, 'inline'),
  ('23ba6a6f-88aa-4b7b-87c0-ac3012089076', '56b72be2-7602-4b82-a6f1-d9fc2438e8a2', $$figuur 1 — blokschema power-to-ammonia (stap 1 t/m 4)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-power-to-ammonia-context3.png$$,
   $$In figuur 1 is het power-to-ammonia-proces met een vereenvoudigd blokschema weergegeven. figuur 1: H₂O gaat naar stap 1, met uitgaand O₂ en H₂; H₂ gaat naar stap 3. Lucht gaat naar stap 2, met uitgaand N₂ (naar stap 3) en gasmengsel X. Stap 3 geeft NH₃(g) aan stap 4, die NH₃(l) aan opslag geeft.$$, 'inline'),
  ('69ff33d4-351c-45d6-8a14-ddefe140d7d8', '56b72be2-7602-4b82-a6f1-d9fc2438e8a2', $$terugwinning van ammoniak tot energie — inleiding$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-power-to-ammonia-context4.png$$,
   $$In tijden waarin te weinig elektriciteit kan worden opgewekt uit zon of wind kan de opgeslagen ammoniak weer worden omgezet tot energie, door de ammoniak als brandstof te gebruiken in elektriciteitscentrales. Dit verloopt als volgt:$$, 'inline'),
  ('7d6a4a02-579f-4296-890e-9fa662f6d3dc', '56b72be2-7602-4b82-a6f1-d9fc2438e8a2', $$stappen 5 en 6 — vloeibaar maken en verbranden van ammoniak$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-power-to-ammonia-context5.png$$,
   $$Stap 5: vloeibare ammoniak wordt gasvormig gemaakt. Stap 6: ammoniakgas wordt onder gecontroleerde omstandigheden verbrand tot stikstof en water in een daarvoor geschikte elektriciteitscentrale.$$, 'inline'),
  ('94f19848-139d-46ae-aaac-e1e1893410a8', '56b72be2-7602-4b82-a6f1-d9fc2438e8a2', $$figuur 2 — volledig blokschema power-to-ammonia inclusief terugwinning$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-power-to-ammonia-context6.png$$,
   $$In figuur 2 is het gehele proces met een vereenvoudigd blokschema weergegeven. figuur 2: zelfde bovenste deel als figuur 1 (H₂O/stap1/O₂/H₂, lucht/stap2/N₂/gasmengsel X, stap3, NH₃(g), stap4, NH₃(l), opslag). Vanaf opslag gaat NH₃(l) naar stap 5, die NH₃(g) geeft aan stap 6; bij stap 6 gaat ook gas Y naar binnen, en komt N₂, H₂O uit.$$, 'inline'),
  ('63807633-ff65-4c5d-8ad5-ef00548328af', '56b72be2-7602-4b82-a6f1-d9fc2438e8a2', $$reactie 1 — verbranding ammoniakgas, reactiewarmte$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-power-to-ammonia-context7.png$$,
   $$Stap 6 vindt plaats onder gecontroleerde omstandigheden, waardoor minder ongewenste bijproducten ontstaan. Deze stap kan netto worden weergegeven met de volgende vergelijking: 4 NH₃ (g) + 3 O₂ (g) → 2 N₂ (g) + 6 H₂O (l) (reactie 1). De reactiewarmte van reactie 1 is –3,83·10⁵ J per mol NH₃.$$, 'inline'),
  ('d7a3c377-3445-4705-9bd5-7c57fb9931a8', '56b72be2-7602-4b82-a6f1-d9fc2438e8a2', $$jaarlijks elektriciteitsverbruik huishouden — 3,3·10³ kWh$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-power-to-ammonia-context8.png$$,
   $$In Nederland verbruikt een gemiddeld huishouden per jaar 3,3·10³ kWh (kilowattuur) aan elektriciteit.$$, 'inline'),
  ('c28d0d86-7d41-4124-a043-a0c3b4212a60', '56b72be2-7602-4b82-a6f1-d9fc2438e8a2', $$vloeibare waterstof als alternatief voor vloeibare ammoniak$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-power-to-ammonia-context9.png$$,
   $$Waterstof die in stap 1 ontstaat, zou in principe ook als brandstof voor een elektriciteitscentrale kunnen dienen. Toch geeft men kennelijk de voorkeur aan vloeibare ammoniak boven vloeibare waterstof om overtollige wind- en zonne-energie in op te slaan.$$, 'inline'),

  ('2899916e-a9fe-4597-98ee-9276291ec43f', 'eb550421-fdec-4290-919b-97a43f111df1', $$inleiding — azijnzuurbacteriën zetten ethanol om tot azijnzuur$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-goede-wijn-context1.png$$,
   $$Wijn kan bederven doordat stoffen in de wijn door micro-organismen worden omgezet. Wijn kan bijvoorbeeld zuur gaan smaken doordat azijnzuurbacteriën, die in wijn aanwezig zijn, ethanol omzetten tot azijnzuur (C₂H₄O₂). De reactie die daarbij optreedt, is een redoxreactie waarbij ethanol als reductor reageert.$$, 'inline'),
  ('ee34b8c7-ea78-4886-9b49-a8bb516f1bdb', 'eb550421-fdec-4290-919b-97a43f111df1', $$sulfiet in wijn — ADI-waarde en wettelijke grens$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-goede-wijn-context2.png$$,
   $$Aan wijn wordt vaak 'sulfiet' toegevoegd, waarmee onder meer oxidatie, kleur en bacteriegroei tijdens het maken van de wijn worden beïnvloed. De naam sulfiet wordt gebruikt om een aantal zwavelhoudende verbindingen aan te duiden. De toegestane hoeveelheid sulfiet in wijn is wettelijk geregeld. Een witte wijn bijvoorbeeld, mag maximaal 200 mg sulfiet per liter bevatten.$$, 'inline'),
  ('6aee0df2-120b-48d1-b59e-1396a2e897eb', 'eb550421-fdec-4290-919b-97a43f111df1', $$chitosan als alternatief voor sulfiet — gemaakt uit chitine en natronloog$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-goede-wijn-context3.png$$,
   $$Omdat sulfiet in verband wordt gebracht met gezondheidsklachten, worden alternatieven onderzocht. Een van deze alternatieven is het gebruik van chitosan. Chitosan is een vaste stof die wordt gemaakt door een reactie van chitine met natronloog. In figuur 1 op de volgende bladzijde is de structuurformule van een fragment chitine (fragment-a) en een mogelijke structuurformule van een fragment chitosan (fragment-b) weergegeven.$$, 'inline'),
  ('aab00cdd-dc0e-4f90-903f-bc5ec85885e1', 'eb550421-fdec-4290-919b-97a43f111df1', $$acetaationen afgesplitst, NH₂-groepen gevormd$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-goede-wijn-context4.png$$,
   $$Bij de reactie van chitine met natronloog worden acetaationen (CH₃COO⁻) afgesplitst, waarbij NH₂-groepen worden gevormd. De reactieomstandigheden bepalen het aantal acetaationen dat van de chitinemoleculen wordt afgesplitst, en daarmee het gemiddelde aantal NH₂-groepen dat per molecuul chitosan wordt gevormd.$$, 'inline'),
  ('b0dca70b-d36b-40eb-80e2-dc5f2add1775', 'eb550421-fdec-4290-919b-97a43f111df1', $$figuur 1 — structuurformules fragment-a (chitine) en fragment-b (chitosan)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-goede-wijn-context5.png$$,
   $$figuur 1: fragment-a (chitine), een keten van vier gekoppelde suikereenheden elk met een acetamidogroep (NH-C(=O)-CH₃). fragment-b (chitosan), dezelfde keten van vier eenheden waarbij twee van de vier acetamidogroepen zijn vervangen door een vrije NH₂-groep.$$, 'inline'),
  ('3a717529-97dd-4424-ac72-ab744450b80e', 'eb550421-fdec-4290-919b-97a43f111df1', $$schematische reactievergelijking chitine → chitosan, onvolledig$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-goede-wijn-context6.png$$,
   $$De reactie waarbij het fragment chitine (fragment-a) met natronloog wordt omgezet tot het fragment chitosan (fragment-b), kan schematisch worden weergegeven als: fragment-a + … X → fragment-b + … CH₃COO⁻. Deze vergelijking is nog onvolledig: twee coëfficiënten en één formule (X) ontbreken.$$, 'inline'),
  ('29246144-b760-4011-ba30-a19dbd127626', 'eb550421-fdec-4290-919b-97a43f111df1', $$reactie stopgezet — niet alle NH₂-groepen gevormd$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-goede-wijn-context7.png$$,
   $$Als de reactie wordt stopgezet zijn nog niet alle mogelijke NH₂-groepen gevormd.$$, 'inline'),
  ('c2acff1b-956c-4bd7-b054-df76fd7f8d90', 'eb550421-fdec-4290-919b-97a43f111df1', $$wijn bestaat voornamelijk uit water, pH ongeveer 3,5$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-goede-wijn-context8.png$$,
   $$Wijn bestaat voornamelijk uit water, en heeft een pH van ongeveer 3,5.$$, 'inline'),
  ('957c593f-1a52-45a6-8c93-9136907458db', 'eb550421-fdec-4290-919b-97a43f111df1', $$genipine — ester behandeling van chitosan bij pH 3,5$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-goede-wijn-context9.png$$,
   $$Bij een pH van 3,5 worden de NH₂-groepen in de moleculen chitosan omgezet tot NH₃⁺-groepen. Door de vorming van NH₃⁺-groepen wordt chitosan oplosbaar in wijn. Om te voorkomen dat het oplost in wijn, wordt chitosan vooraf behandeld met genipine. De structuurformule van genipine is hiernaast weergegeven (een ringstructuur met onder andere een HO-CH₂-groep, een OH-groep en een estergroep -C(=O)-O-CH₃). Genipine is een ester.$$, 'inline'),
  ('335bcd0c-fb34-4062-8cc3-485406c9e9e1', 'eb550421-fdec-4290-919b-97a43f111df1', $$figuur 2 — chitosan verbonden met twee genipine-eenheden (G)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-goede-wijn-context10.png$$,
   $$In figuur 2 is schematisch en vereenvoudigd de structuur weergegeven van chitosan dat is behandeld met genipine. De ketens van chitosan zijn in dit stukje verbonden met twee genipine-eenheden, die met G zijn weergegeven. figuur 2: twee chitosanketens (elk met vier suikereenheden, waarvan sommige met NH₃⁺-groepen) die via twee genipine-eenheden (G-G) een dwarsverbinding vormen tussen een N-atoom van de ene keten en een C-atoom van de andere keten.$$, 'inline'),
  ('212304ea-8b20-40e5-85e0-d3fdfd4af3e1', 'eb550421-fdec-4290-919b-97a43f111df1', $$antibacteriële werking chitosan — ijzerionen en enzymen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-goede-wijn-context11.png$$,
   $$De antibacteriële werking van chitosan blijkt onder meer veroorzaakt te worden doordat chitosan ijzerionen bindt. IJzerionen zijn van nature in wijn aanwezig en spelen een rol in het functioneren van bepaalde enzymen van de azijnzuurbacteriën. Een enzym is een biokatalysator.$$, 'inline'),

  ('d88191d2-2bd1-42d2-b5d1-f818423a07d7', 'a9bb21b8-c248-428c-b3ba-e7ff8f70691e', $$inleiding — NLES als synthetische zeep$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-nles-context1.png$$,
   $$Natriumlaurylethersulfaat (NLES) is een synthetische zeep die wordt toegepast in textielwasmiddelen en in shampoos. NLES is opgebouwd uit natriumionen en laurylethersulfaat-ionen (LES⁻-ionen). NLES is oplosbaar in water. De reinigende werking van NLES berust op de structuur van LES⁻-ionen. In figuur 1 zijn de structuurformule (figuur 1a), de ion-formule (figuur 1b) en de schematische notatie van het LES⁻-ion (figuur 1c) weergegeven.$$, 'inline'),
  ('67981fe6-0021-481f-bc86-eafaa1d45f3a', 'a9bb21b8-c248-428c-b3ba-e7ff8f70691e', $$figuur 1 — structuurformule, ion-formule en schematische notatie LES⁻-ion$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-nles-context2.png$$,
   $$figuur 1: 1a structuurformule van het LES⁻-ion, een lange koolwaterstofketen (12 C-atomen) met daaraan een keten van 3 (OC₂H₄)-eenheden en een sulfaatgroep (OSO₃⁻). 1b ion-formule: C₁₂H₂₅(OC₂H₄)₃OSO₃⁻, met de koolwaterstofstaart aangeduid als hydrofoob en het sulfaatdeel als hydrofiel. 1c schematische notatie: een lijn (hydrofobe staart) met een bolletje (hydrofiele kop).$$, 'inline'),
  ('f6d62db0-4fe7-4c2e-bde5-dff2f2adad44', 'a9bb21b8-c248-428c-b3ba-e7ff8f70691e', $$reinigende werking NLES — beschrijving figuur 2$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-nles-context3.png$$,
   $$In figuur 2 is de reinigende werking van NLES schematisch weergegeven: Een groepje vuilmoleculen dat aanwezig is op een textielvezel wordt omringd door LES⁻-ionen (figuur 2a). Het 'vuil-LES⁻-deeltje' dat daarbij ontstaat, laat vervolgens los van de textielvezel en gaat tussen de watermoleculen zitten (figuur 2b).$$, 'inline'),
  ('52cb5085-b79b-4807-9363-e8bef2af64df', 'a9bb21b8-c248-428c-b3ba-e7ff8f70691e', $$figuur 2 — vuilmoleculen omringd door LES⁻-ionen (2a) en vuil-LES⁻-deeltje tussen watermoleculen (2b)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-nles-context4.png$$,
   $$figuur 2a: textielvezel met daarop vuilmoleculen, omringd door LES⁻-ionen (hydrofobe staarten naar het vuil gericht, hydrofiele koppen naar het water). figuur 2b: een los 'vuil-LES⁻-deeltje' (vuil omringd door LES⁻-ionen met de hydrofiele koppen naar buiten) tussen de watermoleculen, los van de textielvezel.$$, 'inline'),
  ('b9cf0e63-80f1-45e0-b115-f7b9f5ec7137', 'a9bb21b8-c248-428c-b3ba-e7ff8f70691e', $$NLES geproduceerd uit palmpitolie — dodecaan-1-ol tussenproduct$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-nles-context5.png$$,
   $$NLES kan worden geproduceerd uit palmpitolie. Bij de productie van NLES wordt uit palmpitolie eerst dodecaan-1-ol (C₁₂H₂₅OH) gemaakt. Dodecaan-1-ol wordt vervolgens omgezet tot NLES. In figuur 3 zijn de stappen van de productie van dodecaan-1-ol vereenvoudigd in een blokschema weergegeven.$$, 'inline'),
  ('ebc690bf-bc64-4b0d-aedd-4f1e487e2d25', 'a9bb21b8-c248-428c-b3ba-e7ff8f70691e', $$figuur 3 — blokschema palmpitolie tot dodecaan-1-ol (stap 1 t/m 4)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-nles-context6.png$$,
   $$figuur 3: palmpitolie gaat naar stap 1, met water erbij en glycerol eruit, en vetzuren naar stap 2; bij stap 2 komt methanol erbij en water eruit, esters naar stap 3; bij stap 3 komt waterstof erbij en methanol eruit, overige alcoholen naar stap 4; stap 4 geeft dodecaan-1-ol en resterende alcoholen.$$, 'inline'),
  ('826fdad0-3605-4d9c-9fb1-b7b496d19457', 'a9bb21b8-c248-428c-b3ba-e7ff8f70691e', $$stappen 1 t/m 4 — hydrolyse, verestering, hydrogenering, scheiding$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-nles-context7.png$$,
   $$Stap 1: palmpitolie wordt gehydrolyseerd tot vetzuren en glycerol, waarbij de glycerol wordt afgescheiden. Stap 2: de vetzuren worden vervolgens met methanol omgezet tot esters en water. De ontstane waterlaag wordt afgevoerd. Stap 3: de esters worden met waterstof omgezet tot alcoholen, waaronder dodecaan-1-ol en methanol. De methanol wordt direct afgescheiden. Stap 4: dodecaan-1-ol wordt vervolgens gescheiden van de resterende alcoholen.$$, 'inline'),
  ('2f7b96f1-fecf-470b-8039-cce88e56fc20', 'a9bb21b8-c248-428c-b3ba-e7ff8f70691e', $$figuur 4 — structuurformule van een vet uit palmpitolie$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-nles-context8.png$$,
   $$In figuur 4 is een voorbeeld van een vet dat in palmpitolie voorkomt in structuurformule weergegeven. figuur 4: glycerolgedeelte (drie C-atomen) elk veresterd met een vetzuurgedeelte: H₂C-O-C(=O)-C₁₁H₂₃, HC-O-C(=O)-C₁₁H₂₃, H₂C-O-C(=O)-C₁₇H₃₃.$$, 'inline'),
  ('e61e1338-0f90-4670-b59a-33969848b742', 'a9bb21b8-c248-428c-b3ba-e7ff8f70691e', $$hydrolyse van het vet — glycerol, dodecaanzuur en een ander vetzuur$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-nles-context9.png$$,
   $$Bij de hydrolyse van dit vet (stap 1) ontstaan glycerol, dodecaanzuur (C₁₂H₂₄O₂) en één ander vetzuur.$$, 'inline'),
  ('ca2538a1-29e1-4ca4-88b0-c0e78abaa547', 'a9bb21b8-c248-428c-b3ba-e7ff8f70691e', $$scheiding stap 4 op basis van kookpunt$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-nles-context10.png$$,
   $$De scheiding in stap 4 vindt plaats op basis van verschil in kookpunt.$$, 'inline'),
  ('c03a4ece-7215-4b86-aae5-43510c66c45a', 'a9bb21b8-c248-428c-b3ba-e7ff8f70691e', $$recirculatie van stoffen — aannemelijk uit figuur 3$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-nles-context11.png$$,
   $$Uitgaande van figuur 3 is het aannemelijk dat bepaalde stoffen worden gerecirculeerd.$$, 'inline'),
  ('ccbf9e27-7bfb-4e3b-8f7f-26965f758f21', 'a9bb21b8-c248-428c-b3ba-e7ff8f70691e', $$dodecaan-1-ol wordt omgezet tot NLES — onvolledig blokschema figuur 5$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-nles-context12.png$$,
   $$Dodecaan-1-ol wordt vervolgens omgezet tot NLES. Dit is met een onvolledig blokschema weergegeven in figuur 5.$$, 'inline'),
  ('da4c1617-32a6-4621-9294-fd6eaed39e6f', 'a9bb21b8-c248-428c-b3ba-e7ff8f70691e', $$figuur 5 — blokschema dodecaan-1-ol tot NLES (stap 5 t/m 7)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-nles-context13.png$$,
   $$figuur 5: dodecaan-1-ol gaat naar stap 5, met etheenoxide erbij en koelwater als koeling (in en uit), naar stap 6, met zwaveltrioxide erbij, naar stap 7, met natriumhydroxide-oplossing erbij, en opgelost NLES eruit.$$, 'inline'),
  ('ba35e723-b842-4cb6-afc3-d57f13df8c15', 'a9bb21b8-c248-428c-b3ba-e7ff8f70691e', $$stappen 5 t/m 7 — reactievergelijkingen etheenoxide, zwaveltrioxide, NaOH$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-nles-context14.png$$,
   $$Stap 5: dodecaan-1-ol reageert met etheenoxide tot lauryletheralcohol volgens C₁₂H₂₅OH + 3 C₂H₄O → C₁₂H₂₅(OC₂H₄)₃OH. Stap 6: lauryletheralcohol reageert met zwaveltrioxide tot laurylethersulfonzuur (C₁₂H₂₅(OC₂H₄)₃OSO₃H). Stap 7: laurylethersulfonzuur wordt met een natriumhydroxide-oplossing omgezet tot een oplossing van NLES.$$, 'inline'),
  ('f817a511-cc51-4e3e-a636-0ac1bf573408', 'a9bb21b8-c248-428c-b3ba-e7ff8f70691e', $$reactor stap 5 op constante temperatuur$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-nles-context15.png$$,
   $$De reactor waarin stap 5 plaatsvindt, wordt op een constante temperatuur gehouden.$$, 'inline'),
  ('7d472376-3ece-41fa-879b-ab601520058e', 'a9bb21b8-c248-428c-b3ba-e7ff8f70691e', $$vergelijking omzetting laurylethersulfonzuur (stap 7)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-nles-context16.png$$,
   $$De vergelijking van de omzetting van laurylethersulfonzuur (stap 7) is als volgt: C₁₂H₂₅(OC₂H₄)₃OSO₃H + OH⁻ → C₁₂H₂₅(OC₂H₄)₃OSO₃⁻ + H₂O.$$, 'inline'),

  ('0a06bff0-8b1f-476c-ad6d-fbb3ae4b79a6', '2a6d357c-df6c-46db-aa00-558c0330f7b1', $$inleiding — Nordic gold legering in muntgeld$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-nordic-gold-context1.png$$,
   $$De munten van 10, 20 en 50 eurocent zijn gemaakt van 'Nordic gold'. Dit materiaal is een legering van koper, aluminium, zink en tin. In tabel 1 staan enkele gegevens van de atoomsoorten in Nordic gold.$$, 'inline'),
  ('a4257232-ab27-4be7-9e31-bdcb9ec3c9a8', '2a6d357c-df6c-46db-aa00-558c0330f7b1', $$tabel 1 — massapercentage, atoommassa en atoomdiameter Cu, Al, Zn, Sn$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-nordic-gold-context2.png$$,
   $$tabel 1: symbool, massapercentage in Nordic gold (%), gemiddelde atoommassa (u), atoomdiameter (10⁻¹² m). Cu: 89; 63,5; 256. Al: 5,0; 27,0; 286. Zn: 5,0; 65,4; 266. Sn: 1,0; 119; 324.$$, 'inline'),
  ('607f35b0-d705-4a1a-ba05-c21ebba61a90', '2a6d357c-df6c-46db-aa00-558c0330f7b1', $$elektrische-geleidingsvermogen Nordic gold$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-nordic-gold-context3.png$$,
   $$Nordic gold heeft een specifieke samenstelling en daarmee een specifiek elektrische-geleidingsvermogen. Het elektrische-geleidingsvermogen kan gebruikt worden voor de herkenning van munten in muntgeldautomaten. Dit geleidingsvermogen is een gevolg van de aanwezigheid van beweeglijke geladen deeltjes.$$, 'inline'),
  ('5295387d-edc2-454d-ba2b-3a8c715ba372', '2a6d357c-df6c-46db-aa00-558c0330f7b1', $$hardheid Nordic gold — invloed atoomdiameter$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-nordic-gold-context4.png$$,
   $$Nordic gold is harder en moeilijker vervormbaar dan zuiver koper. Dit wordt onder andere veroorzaakt door de microstructuur van Nordic gold. De hardheid wordt bepaald door de atoomdiameter van de toegevoegde metaalatomen. De invloed van de tin-atomen en de zink-atomen op de hardheid is weergegeven in figuur 1a. Ook is schematisch weergegeven hoe een Sn-atoom en een Zn-atoom zich tussen de Cu-atomen bevinden (figuur 1b).$$, 'inline'),
  ('fce4c0d8-8792-4b44-ab9a-ab73ffd590a3', '2a6d357c-df6c-46db-aa00-558c0330f7b1', $$figuur 1 — hardheid vs. massapercentage (1a) en Sn/Zn tussen Cu-atomen (1b)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-nordic-gold-context5.png$$,
   $$figuur 1a: grafiek hardheid koperlegering tegen massapercentage toegevoegd metaal, met drie lijnen I, II en III vanuit de oorsprong, en de lijnen Sn en Zn expliciet benoemd. Lijn Sn loopt het steilst, dan lijn II, dan lijn I nog steiler dan Sn bij lage percentages maar afgebroken, en lijn Zn en III minder steil. figuur 1b: twee roostertekeningen, boven een Sn-atoom (groter, lichter) tussen Cu-atomen, onder een Zn-atoom tussen Cu-atomen, beide met streepjes tussen de atomen getekend.$$, 'inline'),
  ('dfb9c2a8-5d34-40a6-a17e-78a48116b019', '2a6d357c-df6c-46db-aa00-558c0330f7b1', $$streepjes in figuur 1b zijn geen echte bindingsstreepjes$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-nordic-gold-context6.png$$,
   $$In figuur 1b is de invloed van de atoomdiameter van de toegevoegde metaalatomen op het rooster te zien. De atomen zijn met streepjes verbonden. Dit is echter een onjuiste weergave van het type binding tussen de atomen in Nordic gold. De streepjes in figuur 1b zijn geen echte bindingsstreepjes zoals die worden gebruikt in structuurformules van moleculaire stoffen, maar ze geven wel een interactie weer tussen de atomen waaruit deze legering is samengesteld.$$, 'inline'),
  ('689b9006-0ceb-4cc1-87dc-65022f51ded4', '2a6d357c-df6c-46db-aa00-558c0330f7b1', $$een van de lijnen I, II, III geeft invloed van aluminiumatomen weer$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-nordic-gold-context7.png$$,
   $$Een van de lijnen I, II en III in figuur 1a geeft de invloed van aluminiumatomen op de hardheid van een koperlegering weer.$$, 'inline'),
  ('1508ef2a-f5aa-4a56-89c0-6e19dd2b1a35', '2a6d357c-df6c-46db-aa00-558c0330f7b1', $$corrosie aan het oppervlak van de munten — Cu₂O en aluminiumoxide$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-nordic-gold-context8.png$$,
   $$Aan het oppervlak van de munten kan corrosie plaatsvinden, waardoor geoxideerd koper in de vorm van koper(I)oxide (Cu₂O) en geoxideerd aluminium (aluminiumoxide) kunnen ontstaan. Doordat aluminium minder edel is dan koper oxideert het eerder dan koper. Geoxideerd aluminium beperkt de corrosiegevoeligheid van Nordic gold.$$, 'inline'),
  ('ab7acf5c-849d-4ef0-9fda-ab6d3b47db8f', '2a6d357c-df6c-46db-aa00-558c0330f7b1', $$reactie 1 en 2 — antibacteriële werking koperlegeringen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-nordic-gold-context9.png$$,
   $$Koperlegeringen hebben een antibacteriële werking, die onder meer veroorzaakt wordt door de volgende twee reacties: 2 Cu⁺ + 2 H⁺ + O₂ → 2 Cu²⁺ + H₂O₂ (reactie 1). 2 Cu²⁺ + 2 R-SH → 2 Cu⁺ + R-S-S-R + 2 H⁺ (reactie 2).$$, 'inline'),
  ('d941300d-4cbb-43b8-b36d-9a93a2a05ab0', '2a6d357c-df6c-46db-aa00-558c0330f7b1', $$waterstofperoxide beschadigt celmembranen, Cu²⁺ reageert met SH-groepen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-nordic-gold-context10.png$$,
   $$Waterstofperoxide (H₂O₂), dat ontstaan is bij reactie 1, beschadigt de celmembranen van bacteriën. Bij reactie 1 ontstaan ook Cu²⁺-ionen. Cu²⁺-ionen reageren met de SH-groepen in eiwitten van bacteriën (reactie 2). In de vergelijking van deze reactie is het eiwit weergegeven met R-SH. Uiteindelijk sterven bacteriën als gevolg van de opgelopen schade.$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('cec3610e-fc9d-4d0f-a497-bcc1097d9410', '1dcee0c7-abf1-4fd0-b340-0c043e30e2c0', 1,
   '[{"domain": "Technologie en duurzaamheid", "subdomain": "Energieomzettingen"}]'::jsonb,
   '["biobrandstof", "fossiele brandstof", "broeikaseffect", "koolstofkringloop", "duurzaamheid"]'::jsonb,
   $$Uitleggen waarom verbranding van fossiele brandstoffen sterker bijdraagt aan het versterkt broeikaseffect dan verbranding van biobrandstoffen.$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-hexaan-uit-cellulose-vraag1.png$$,
   $$Leg uit dat het verbranden van fossiele brandstoffen een grotere bijdrage levert aan het versterkt broeikaseffect dan het verbranden van biobrandstoffen.$$, array['e4f57407-1924-4c76-baef-7e28f7511c72']::uuid[]),
  ('e6e5c664-f948-443c-939b-2d3dc575bc91', '1dcee0c7-abf1-4fd0-b340-0c043e30e2c0', 2,
   '[{"domain": "Reacties", "subdomain": "Chemische processen"}]'::jsonb,
   '["cellulose", "polysacharide", "hydrolyse", "glucose", "structuurformule"]'::jsonb,
   $$Completeren van de reactievergelijking van de hydrolyse van het uiteinde van een cellulosemolecuul tot twee glucosemoleculen, in structuurformules.$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-hexaan-uit-cellulose-vraag2.png$$,
   $$Maak op de uitwerkbijlage de reactievergelijking compleet van de hydrolyse van het uiteinde van het gegeven cellulosemolecuul. − Laat hierbij twee losse moleculen glucose afsplitsen. − Gebruik structuurformules.$$, array['c40a7189-8809-4f03-a853-3bb2e7d61583', 'de306272-8d57-4363-aa95-0c706cf5fb60']::uuid[]),
  ('7a47ff7b-80cf-4a1f-9b0c-b7c0bb81988c', '1dcee0c7-abf1-4fd0-b340-0c043e30e2c0', 3,
   '[{"domain": "Reacties", "subdomain": "Chemische processen"}]'::jsonb,
   '["glucose", "hydrogenering", "hexaan", "molecuulformule", "reactievergelijking"]'::jsonb,
   $$Opstellen van de vergelijking in molecuulformules van de omzetting van glucose met waterstof tot hexaan en water.$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-hexaan-uit-cellulose-vraag3.png$$,
   $$Geef de vergelijking in molecuulformules van de reactie van glucose met waterstof tot hexaan en water.$$, array['4a9261ec-8e06-45ee-8abe-cdd9b014f48f']::uuid[]),
  ('9b41290b-a1bd-466c-bab8-480428b2b996', '1dcee0c7-abf1-4fd0-b340-0c043e30e2c0', 4,
   '[{"domain": "Materie", "subdomain": "Bindingen en eigenschappen"}]'::jsonb,
   '["dodecaan", "apolair", "mengbaarheid", "vanderwaalsbinding", "waterstofbrug"]'::jsonb,
   $$Verklaren waarom water en dodecaan niet goed mengen aan de hand van de apolaire formule van dodecaan.$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2022-i-hexaan-uit-cellulose-vraag4.png$$,
   $$Geef hiervoor een verklaring aan de hand van de formule van dodecaan.$$, array['68a4331a-e994-4263-a760-c6506f98faa7']::uuid[]),
  ('0edbf9f6-1cbc-4208-813f-945acc52d84d', '1dcee0c7-abf1-4fd0-b340-0c043e30e2c0', 5,
   '[{"domain": "Rekenen en analyse", "subdomain": "Grootheden en relaties"}]'::jsonb,
   '["reactiesnelheid", "significante cijfers", "molariteit", "reactietijd", "hexaanvorming"]'::jsonb,
   $$Berekenen van de gemiddelde reactiesnelheid van hexaanvorming in mol per L water per seconde.$$,
